// 日本語にカタカナ語として定着している英語の台帳（暗記の手がかり）。
//
// kana は、日本語でふつうに使われている形。単独でも、よく使う複合語の一部でもよい
// （day ならバレンタインデーのデー、shoe ならシューズ）。
// note は、日本語での意味や使い方が英語とずれていて、そのまま英語に持ち込むと誤るときに書く
// （バイクは英語ではふつう自転車、スマートは英語に「細い」の意味がない、など）。
// scene は、日本語でそのカタカナが使われる場面の例（advantage ならテニスの「アドバンテージ」）。
// カタカナを見て、日本語のどこで聞く言葉かを思い出せるように書く。日本語だけで書き、そのカタカナを必ず入れる。
// 同じカタカナが別の英単語や別の品詞から来ていて取り違えやすいとき（フェイントは feint、
// ホイルは名詞の foil）や、由来を知ると語が結びつくとき（トレンチコート）にも書く。
//
// 定着しているかどうか、意味がずれているかどうかは人が判断する。
// 機械が確かめるのは、見出し語が辞書にあることと、kana がカタカナで書かれていることだけ。
